// --- Helper Function: Package name to SKU mapping ---
function getProductSKU(packageName) {
  if (!packageName) return null;

  const name = packageName;

  if (name.includes('ثلاثية') || name.includes('3 شهور') || name.includes('ثلاث')) {
    return { sku: 'BUNDLE-15', price: 2500, name: 'Lipo Fit - Triple Package' };
  }
  if (name.includes('مزدوجة') || name.includes('شهرين') || name.includes('2 شهور')) {
    return { sku: 'BUNDLE-14', price: 1850, name: 'Lipo Fit - Double Package' };
  }
  if (name.includes('كاملة') || name.includes('فل') || name.includes('الفل')) {
    return { sku: 'BUNDLE-16', price: 1250, name: 'Lipo Fit - Full Package' };
  }
  if (name.includes('شهر') || name.includes('الشهر')) {
    return { sku: 'BUNDLE-13', price: 1000, name: 'Lipo Fit - Single Package' };
  }
  if (name.includes('تجربة') || name.includes('علبة')) {
    return { sku: 'BUNDLE-17', price: 650, name: 'Lipo Fit - Trial Package' };
  }

  return null;
}

// --- Helper Function: Extract order data from Arabic text ---
function extractOrderDataFromText(text) {
  const result = {
    hasData: false,
    customer_name: null,
    customer_phone: null,
    full_address: null,
    state_name: null,
    city_name: null,
    official_city_name: null,
    product_sku: null,
    product_name: null,
    product_price: 0,
    discount: 0,
    quantity: 1,
    shipping_price: 0,
    total_price: 0
  };

  // Extract name - multiple patterns
  const namePatterns = [
    /تمام\s+يا\s+([^\s!،,🎉💚\n]+)/,           // "تمام يا خديجة"
    /ممتاز\s+يا\s+([^\s!،,🎉💚\n]+)/,          // "ممتاز يا خديجة"
    /اتمام\s+يا\s+([^\s!،,🎉💚\n]+)/,          // "اتمام يا خديجة"
    /(?:يا)\s+([^\s!،,🎉💚\n]+)(?:\s*[!🎉💚])/,  // "يا خديجة!" or "يا خديجة 🎉"
    /(?:أستاذ|أستاذة)\s+([^\s!،,🎉💚\n]+)/,    // "أستاذ أحمد"
    /(?:الاسم|اسم)[:\s]*([^\n،,]+)/            // "الاسم: خديجة"
  ];

  for (const pattern of namePatterns) {
    const match = text.match(pattern);
    if (match) {
      result.customer_name = match[1].trim();
      result.hasData = true;
      break;
    }
  }

  // Extract phone number (Egyptian format)
  const phoneMatch = text.match(/(?:الموبايل|الهاتف|رقم|تليفون|📱)[:\s]*(\d{10,11})/);
  if (phoneMatch) {
    result.customer_phone = phoneMatch[1];
    result.hasData = true;
  }

  // Extract address
  const addressMatch = text.match(/(?:العنوان|عنوان|📍)[:\s]*([^\n]+)/);
  if (addressMatch) {
    result.full_address = addressMatch[1].trim();
    result.hasData = true;
  }

  // Extract price breakdown: "2500 + 95 شحن = 2595" or "2500ج + 95ج"
  const priceMatch = text.match(/(\d+)\s*(?:ج|جنيه)?\s*[+]\s*(\d+)\s*(?:ج|جنيه)?\s*(?:شحن|توصيل)?\s*=\s*(\d+)/);
  if (priceMatch) {
    result.product_price = parseInt(priceMatch[1]);
    result.shipping_price = parseInt(priceMatch[2]);
    result.total_price = parseInt(priceMatch[3]);
    result.hasData = true;
  }

  // Extract single total price if no breakdown
  if (!result.total_price) {
    const totalMatch = text.match(/(?:الإجمالي|المجموع|السعر)[:\s]*(\d+)/);
    if (totalMatch) {
      result.total_price = parseInt(totalMatch[1]);
      result.hasData = true;
    }
  }

  // Extract package/product name and map to SKU
  const packageMatch = text.match(/(?:الباقة|المنتج|الطلب|📦)[:\s]*([^\n،,]+)/);
  if (packageMatch) {
    const rawPackageName = packageMatch[1].trim();
    result.product_name = rawPackageName;

    // Map to SKU
    const skuData = getProductSKU(rawPackageName);
    if (skuData) {
      result.product_sku = skuData.sku;
      result.product_name = skuData.name;
      if (!result.product_price) {
        result.product_price = skuData.price;
      }
    }
    result.hasData = true;
  }

  return result;
}

// --- Robust JSON Parser for AI Agent Output (v2.0 with Fallback) ---
const rawOutputString = $input.first().json.output;

// 1. Initial validation of the input.
if (!rawOutputString || typeof rawOutputString !== 'string') {
  return [{ json: { error: "Input field 'output' from AI Agent is missing or not a string." } }];
}

let jsonString = null;
let parsedJson = null;

// --- STRATEGY 1: Find a Markdown Code Fence (Most Reliable) ---
const markdownRegex = /`{3,}(?:json)?\s*([\s\S]*?)\s*`{3,}/;
const markdownMatch = rawOutputString.match(markdownRegex);

if (markdownMatch && markdownMatch[1]) {
  jsonString = markdownMatch[1].trim();
}

// --- STRATEGY 2: Find First '{' and Last '}' (Substring Search) ---
if (!jsonString) {
  const startIndex = rawOutputString.indexOf('{');
  const endIndex = rawOutputString.lastIndexOf('}');
  if (startIndex > -1 && endIndex > -1 && endIndex > startIndex) {
    jsonString = rawOutputString.substring(startIndex, endIndex + 1).trim();
  }
}

// --- STRATEGY 3: FALLBACK - Treat as plain text response ---
if (!jsonString) {
  console.log("FALLBACK ACTIVATED: AI returned plain text, wrapping in JSON");
  const extractedData = extractOrderDataFromText(rawOutputString.trim());
  return [{ 
    json: {
      intent: "normal_conversation",
      botResponse: rawOutputString.trim(),
      orderData: extractedData.hasData ? extractedData : null,
      telegramData: null
    }
  }];
}

// 3. Attempt to parse the extracted JSON string.
try {
  parsedJson = JSON.parse(jsonString);

  // Validate required fields exist
  if (!parsedJson.intent) {
    parsedJson.intent = "normal_conversation";
  }
  if (!parsedJson.botResponse && parsedJson.botResponse !== "") {
    parsedJson.botResponse = rawOutputString.trim();
  }
  if (parsedJson.orderData === undefined) {
    parsedJson.orderData = null;
  }
  if (parsedJson.telegramData === undefined) {
    parsedJson.telegramData = null;
  }

  // --- STRATEGY 5: Extract orderData from botResponse if null ---
  if (parsedJson.orderData === null && parsedJson.botResponse) {
    const extractedData = extractOrderDataFromText(parsedJson.botResponse);
    if (extractedData.hasData) {
      parsedJson.orderData = extractedData;
    }
  }

  return [{ json: parsedJson }];

} catch (error) {
  // --- STRATEGY 4: Try fixing common JSON issues ---
  try {
    let fixedJsonString = jsonString
      .replace(/\n/g, '\\n')
      .replace(/\r/g, '\\r')
      .replace(/\t/g, '\\t');

    parsedJson = JSON.parse(fixedJsonString);

    if (!parsedJson.intent) {
      parsedJson.intent = "normal_conversation";
    }
    if (parsedJson.orderData === undefined) {
      parsedJson.orderData = null;
    }
    if (parsedJson.telegramData === undefined) {
      parsedJson.telegramData = null;
    }

    // --- STRATEGY 5: Extract orderData from botResponse if null ---
    if (parsedJson.orderData === null && parsedJson.botResponse) {
      const extractedData = extractOrderDataFromText(parsedJson.botResponse);
      if (extractedData.hasData) {
        parsedJson.orderData = extractedData;
      }
    }

    return [{ json: parsedJson }];

  } catch (retryError) {
    console.log("FINAL FALLBACK: All parsing failed, using raw text");
    const extractedData = extractOrderDataFromText(rawOutputString.trim());
    return [{ 
      json: {
        intent: "normal_conversation",
        botResponse: rawOutputString.trim(),
        orderData: extractedData.hasData ? extractedData : null,
        telegramData: null
      }
    }];
  }
}

